insert into public.lessons(id,slug,revision,kind,grade,aspect,title,data,status) values('d11ad937-b133-4b61-8910-67d006554938','sd-kalimat',1,'lesson','SD','kalimat','Kalimat tentang hewan','{"description":"Susun kalimat sederhana dengan kosakata hewan dari video.","emoji":"🐔","word":"Ayam","words":["Ayam","Kambing","Ikan"],"time":10,"intro":"Kamu akan memakai nama hewan untuk menyusun kalimat yang mudah dipahami.","explanation":"Kalimat “Ayam makan jagung.” menyebutkan hewan, kegiatan, dan makanannya. “Ikan berenang di kolam.” menjelaskan kegiatan ikan dan tempatnya.","tip":"Mulai dari hewannya, lalu kegiatannya, lalu tambahkan informasi lain.","visual":"🐔 🌽","level":"Dasar","wordEntry":{"word":"Ayam","emoji":"🐔","category":"Hewan","meaning":"Hewan unggas yang memiliki paruh, sayap, dan dua kaki.","example":"Ayam dapat dipelihara di rumah.","videoId":"3KepM1ycETA","start":75,"video":{"id":"3KepM1ycETA","title":"Mengenal hewan peliharaan","creator":"Direktorat PKPLK","topic":"Kosakata hewan","sourceLevel":"SDLB · Kelas 4","audience":"tunarungu","accessibility":"Isyarat, gambar & teks","description":"Pelajari nama dan ciri hewan peliharaan melalui materi tematik kelas 4 SDLB tunarungu dengan penjelasan isyarat dan gambar.","sourceTitle":"Pembelajaran tematik kelas IV SDLB Tunarungu \"Hewan Peliharaan\""}},"relatedWords":[{"word":"Ayam","emoji":"🐔","category":"Hewan","meaning":"Hewan unggas yang memiliki paruh, sayap, dan dua kaki.","example":"Ayam dapat dipelihara di rumah.","videoId":"3KepM1ycETA","start":75,"video":{"id":"3KepM1ycETA","title":"Mengenal hewan peliharaan","creator":"Direktorat PKPLK","topic":"Kosakata hewan","sourceLevel":"SDLB · Kelas 4","audience":"tunarungu","accessibility":"Isyarat, gambar & teks","description":"Pelajari nama dan ciri hewan peliharaan melalui materi tematik kelas 4 SDLB tunarungu dengan penjelasan isyarat dan gambar.","sourceTitle":"Pembelajaran tematik kelas IV SDLB Tunarungu \"Hewan Peliharaan\""}},{"word":"Kambing","emoji":"🐐","category":"Hewan","meaning":"Hewan berkaki empat yang biasa dipelihara sebagai ternak.","example":"Kambing berada di dalam kandang.","videoId":"3KepM1ycETA","start":110,"video":{"id":"3KepM1ycETA","title":"Mengenal hewan peliharaan","creator":"Direktorat PKPLK","topic":"Kosakata hewan","sourceLevel":"SDLB · Kelas 4","audience":"tunarungu","accessibility":"Isyarat, gambar & teks","description":"Pelajari nama dan ciri hewan peliharaan melalui materi tematik kelas 4 SDLB tunarungu dengan penjelasan isyarat dan gambar.","sourceTitle":"Pembelajaran tematik kelas IV SDLB Tunarungu \"Hewan Peliharaan\""}},{"word":"Ikan","emoji":"🐟","category":"Hewan","meaning":"Hewan yang hidup di air dan bernapas dengan insang.","example":"Ikan berenang di kolam.","videoId":"3KepM1ycETA","start":165,"video":{"id":"3KepM1ycETA","title":"Mengenal hewan peliharaan","creator":"Direktorat PKPLK","topic":"Kosakata hewan","sourceLevel":"SDLB · Kelas 4","audience":"tunarungu","accessibility":"Isyarat, gambar & teks","description":"Pelajari nama dan ciri hewan peliharaan melalui materi tematik kelas 4 SDLB tunarungu dengan penjelasan isyarat dan gambar.","sourceTitle":"Pembelajaran tematik kelas IV SDLB Tunarungu \"Hewan Peliharaan\""}}],"example":"Ayam dapat dipelihara di rumah.","video":{"id":"3KepM1ycETA","title":"Mengenal hewan peliharaan","creator":"Direktorat PKPLK","topic":"Kosakata hewan","sourceLevel":"SDLB · Kelas 4","audience":"tunarungu","accessibility":"Isyarat, gambar & teks","description":"Pelajari nama dan ciri hewan peliharaan melalui materi tematik kelas 4 SDLB tunarungu dengan penjelasan isyarat dan gambar.","sourceTitle":"Pembelajaran tematik kelas IV SDLB Tunarungu \"Hewan Peliharaan\""}}'::jsonb,'published') on conflict(id) do nothing;
