insert into public.lessons(id,slug,revision,kind,grade,aspect,title,data,status) values('a5164f71-54b9-424b-8aae-9362fcf1963e','smp-bacaan',1,'lesson','SMP','bacaan','Rekreasi ke pelabuhan','{"description":"Temukan informasi penting dalam paragraf tentang rekreasi.","emoji":"🚢","word":"Pelabuhan","words":["Pelabuhan","Rekreasi"],"time":10,"intro":"Kamu akan membaca paragraf baru dengan kosakata dari video pemahaman bacaan SMP.","explanation":"Pada hari Minggu, Rani berekreasi bersama keluarga ke pelabuhan. Mereka melihat kapal berlabuh. Kapal menaikkan penumpang. Rani mencatat kegiatan di pelabuhan untuk diceritakan di sekolah.","tip":"Cari siapa, kapan, tempat, dan kegiatan. Gunakan informasi dalam paragraf untuk menjawab.","visual":"🚢 🏖️","level":"Menengah","wordEntry":{"word":"Pelabuhan","emoji":"🚢","category":"Tempat","meaning":"Tempat kapal berlabuh untuk menaikkan atau menurunkan penumpang dan barang.","example":"Kapal berhenti di pelabuhan.","videoId":"XmiXc0YUrXY","start":585,"video":{"id":"XmiXc0YUrXY","title":"Memahami isi paragraf sederhana","creator":"Melalita Anggraeni","topic":"Pemahaman bacaan","sourceLevel":"SMPLB · Kelas 9","audience":"tunarungu","accessibility":"Isyarat & media visual","description":"Amati rekaman pembelajaran kelas 9 tunarungu untuk memahami paragraf sederhana dengan interaksi isyarat dan media visual.","sourceTitle":"VIDEO PEMBELAJARAN SISWA TUNARUNGU KELAS IX BAHASA INDONESIA"}},"relatedWords":[{"word":"Pelabuhan","emoji":"🚢","category":"Tempat","meaning":"Tempat kapal berlabuh untuk menaikkan atau menurunkan penumpang dan barang.","example":"Kapal berhenti di pelabuhan.","videoId":"XmiXc0YUrXY","start":585,"video":{"id":"XmiXc0YUrXY","title":"Memahami isi paragraf sederhana","creator":"Melalita Anggraeni","topic":"Pemahaman bacaan","sourceLevel":"SMPLB · Kelas 9","audience":"tunarungu","accessibility":"Isyarat & media visual","description":"Amati rekaman pembelajaran kelas 9 tunarungu untuk memahami paragraf sederhana dengan interaksi isyarat dan media visual.","sourceTitle":"VIDEO PEMBELAJARAN SISWA TUNARUNGU KELAS IX BAHASA INDONESIA"}},{"word":"Rekreasi","emoji":"🏖️","category":"Kegiatan","meaning":"Kegiatan untuk menyegarkan pikiran atau bersenang-senang.","example":"Kita berekreasi bersama keluarga.","videoId":"XmiXc0YUrXY","start":285,"video":{"id":"XmiXc0YUrXY","title":"Memahami isi paragraf sederhana","creator":"Melalita Anggraeni","topic":"Pemahaman bacaan","sourceLevel":"SMPLB · Kelas 9","audience":"tunarungu","accessibility":"Isyarat & media visual","description":"Amati rekaman pembelajaran kelas 9 tunarungu untuk memahami paragraf sederhana dengan interaksi isyarat dan media visual.","sourceTitle":"VIDEO PEMBELAJARAN SISWA TUNARUNGU KELAS IX BAHASA INDONESIA"}}],"example":"Kapal berhenti di pelabuhan.","video":{"id":"XmiXc0YUrXY","title":"Memahami isi paragraf sederhana","creator":"Melalita Anggraeni","topic":"Pemahaman bacaan","sourceLevel":"SMPLB · Kelas 9","audience":"tunarungu","accessibility":"Isyarat & media visual","description":"Amati rekaman pembelajaran kelas 9 tunarungu untuk memahami paragraf sederhana dengan interaksi isyarat dan media visual.","sourceTitle":"VIDEO PEMBELAJARAN SISWA TUNARUNGU KELAS IX BAHASA INDONESIA"}}'::jsonb,'published') on conflict(id) do nothing;
