insert into public.lessons(id,slug,revision,kind,grade,aspect,title,data,status) values('767645cb-dd72-4fd0-89ee-ee7c00bcb7c5','sma-eksplanasi',1,'lesson','SMA','bacaan','Memahami teks eksplanasi','{"description":"Temukan proses dan sebab peristiwa dalam bacaan sederhana.","emoji":"📝","word":"Eksplanasi","words":["Eksplanasi","Hujan","Banjir"],"time":12,"intro":"Kamu akan membaca contoh eksplanasi yang dibuat untuk latihan dengan kosakata dari video dan Kamus Visual SMA.","explanation":"Hujan deras menambah jumlah air di suatu wilayah. Air biasanya mengalir melalui saluran. Jika saluran tersumbat, air sulit mengalir dan dapat meluap. Luapan air menggenangi jalan yang biasanya kering. Peristiwa ini disebut banjir.","tip":"Temukan peristiwa yang dibahas, lalu urutkan prosesnya. Bedakan penyebab dengan akibat.","visual":"🌧️ 📝 🌊","level":"Lanjutan","wordEntry":{"word":"Eksplanasi","emoji":"📝","category":"Teks","meaning":"Penjelasan tentang bagaimana atau mengapa suatu peristiwa terjadi.","example":"Teks eksplanasi menjelaskan proses terjadinya hujan.","videoId":"cvwI6-6lfGY","start":75,"video":{"id":"cvwI6-6lfGY","title":"Memahami teks eksplanasi","creator":"SMALB KM","topic":"Teks eksplanasi","sourceLevel":"SMALB-B","audience":"tunarungu","accessibility":"Isyarat & teks pada layar","description":"Pelajari teks eksplanasi dari SMALB-B Karya Mulia Surabaya melalui penjelasan isyarat dan teks yang tampil di layar.","sourceTitle":"Video Bahasa Indonesia SMALB_B Karya Mulia Surabaya"}},"relatedWords":[{"word":"Eksplanasi","emoji":"📝","category":"Teks","meaning":"Penjelasan tentang bagaimana atau mengapa suatu peristiwa terjadi.","example":"Teks eksplanasi menjelaskan proses terjadinya hujan.","videoId":"cvwI6-6lfGY","start":75,"video":{"id":"cvwI6-6lfGY","title":"Memahami teks eksplanasi","creator":"SMALB KM","topic":"Teks eksplanasi","sourceLevel":"SMALB-B","audience":"tunarungu","accessibility":"Isyarat & teks pada layar","description":"Pelajari teks eksplanasi dari SMALB-B Karya Mulia Surabaya melalui penjelasan isyarat dan teks yang tampil di layar.","sourceTitle":"Video Bahasa Indonesia SMALB_B Karya Mulia Surabaya"}},{"word":"Hujan","emoji":"🌧️","category":"Peristiwa","meaning":"Air yang jatuh dari awan ke permukaan bumi dalam bentuk titik-titik air.","example":"Hujan merupakan salah satu peristiwa alam.","videoId":"cvwI6-6lfGY","start":165,"video":{"id":"cvwI6-6lfGY","title":"Memahami teks eksplanasi","creator":"SMALB KM","topic":"Teks eksplanasi","sourceLevel":"SMALB-B","audience":"tunarungu","accessibility":"Isyarat & teks pada layar","description":"Pelajari teks eksplanasi dari SMALB-B Karya Mulia Surabaya melalui penjelasan isyarat dan teks yang tampil di layar.","sourceTitle":"Video Bahasa Indonesia SMALB_B Karya Mulia Surabaya"}},{"word":"Banjir","emoji":"🌊","category":"Peristiwa","meaning":"Peristiwa meluapnya air sehingga menggenangi wilayah yang biasanya kering.","example":"Air yang meluap dapat menyebabkan banjir.","videoId":"cvwI6-6lfGY","start":165,"video":{"id":"cvwI6-6lfGY","title":"Memahami teks eksplanasi","creator":"SMALB KM","topic":"Teks eksplanasi","sourceLevel":"SMALB-B","audience":"tunarungu","accessibility":"Isyarat & teks pada layar","description":"Pelajari teks eksplanasi dari SMALB-B Karya Mulia Surabaya melalui penjelasan isyarat dan teks yang tampil di layar.","sourceTitle":"Video Bahasa Indonesia SMALB_B Karya Mulia Surabaya"}}],"example":"Teks eksplanasi menjelaskan proses terjadinya hujan.","video":{"id":"cvwI6-6lfGY","title":"Memahami teks eksplanasi","creator":"SMALB KM","topic":"Teks eksplanasi","sourceLevel":"SMALB-B","audience":"tunarungu","accessibility":"Isyarat & teks pada layar","description":"Pelajari teks eksplanasi dari SMALB-B Karya Mulia Surabaya melalui penjelasan isyarat dan teks yang tampil di layar.","sourceTitle":"Video Bahasa Indonesia SMALB_B Karya Mulia Surabaya"}}'::jsonb,'published') on conflict(id) do nothing;
