insert into public.lessons(id,slug,revision,kind,grade,aspect,title,data,status) values('1b0a820c-c84b-4f0b-8be3-c83691421738','sma-data',1,'lesson','SMA','akademik','Membaca data dalam laporan','{"description":"Hitung dan bandingkan data contoh dalam konteks hujan.","emoji":"📊","word":"Hujan","words":["Hujan","Banjir","Eksplanasi"],"time":12,"intro":"Kamu akan membandingkan angka pada data contoh dan menulis kesimpulan yang sesuai.","explanation":"Data latihan: Senin 10 mm, Selasa 20 mm, Rabu 30 mm. Totalnya 60 mm. Rata-rata tiga hari adalah 60 ÷ 3 = 20 mm. Data ini hanya untuk latihan dan tidak dipakai untuk memprediksi banjir.","tip":"Jumlahkan semua nilai untuk total. Bagi total dengan jumlah hari untuk rata-rata. Kesimpulan harus sesuai data.","visual":"📊 🌧️","level":"Lanjutan","wordEntry":{"word":"Hujan","emoji":"🌧️","category":"Peristiwa","meaning":"Air yang jatuh dari awan ke permukaan bumi dalam bentuk titik-titik air.","example":"Hujan merupakan salah satu peristiwa alam.","videoId":"cvwI6-6lfGY","start":165,"video":{"id":"cvwI6-6lfGY","title":"Memahami teks eksplanasi","creator":"SMALB KM","topic":"Teks eksplanasi","sourceLevel":"SMALB-B","audience":"tunarungu","accessibility":"Isyarat & teks pada layar","description":"Pelajari teks eksplanasi dari SMALB-B Karya Mulia Surabaya melalui penjelasan isyarat dan teks yang tampil di layar.","sourceTitle":"Video Bahasa Indonesia SMALB_B Karya Mulia Surabaya"}},"relatedWords":[{"word":"Hujan","emoji":"🌧️","category":"Peristiwa","meaning":"Air yang jatuh dari awan ke permukaan bumi dalam bentuk titik-titik air.","example":"Hujan merupakan salah satu peristiwa alam.","videoId":"cvwI6-6lfGY","start":165,"video":{"id":"cvwI6-6lfGY","title":"Memahami teks eksplanasi","creator":"SMALB KM","topic":"Teks eksplanasi","sourceLevel":"SMALB-B","audience":"tunarungu","accessibility":"Isyarat & teks pada layar","description":"Pelajari teks eksplanasi dari SMALB-B Karya Mulia Surabaya melalui penjelasan isyarat dan teks yang tampil di layar.","sourceTitle":"Video Bahasa Indonesia SMALB_B Karya Mulia Surabaya"}},{"word":"Banjir","emoji":"🌊","category":"Peristiwa","meaning":"Peristiwa meluapnya air sehingga menggenangi wilayah yang biasanya kering.","example":"Air yang meluap dapat menyebabkan banjir.","videoId":"cvwI6-6lfGY","start":165,"video":{"id":"cvwI6-6lfGY","title":"Memahami teks eksplanasi","creator":"SMALB KM","topic":"Teks eksplanasi","sourceLevel":"SMALB-B","audience":"tunarungu","accessibility":"Isyarat & teks pada layar","description":"Pelajari teks eksplanasi dari SMALB-B Karya Mulia Surabaya melalui penjelasan isyarat dan teks yang tampil di layar.","sourceTitle":"Video Bahasa Indonesia SMALB_B Karya Mulia Surabaya"}},{"word":"Eksplanasi","emoji":"📝","category":"Teks","meaning":"Penjelasan tentang bagaimana atau mengapa suatu peristiwa terjadi.","example":"Teks eksplanasi menjelaskan proses terjadinya hujan.","videoId":"cvwI6-6lfGY","start":75,"video":{"id":"cvwI6-6lfGY","title":"Memahami teks eksplanasi","creator":"SMALB KM","topic":"Teks eksplanasi","sourceLevel":"SMALB-B","audience":"tunarungu","accessibility":"Isyarat & teks pada layar","description":"Pelajari teks eksplanasi dari SMALB-B Karya Mulia Surabaya melalui penjelasan isyarat dan teks yang tampil di layar.","sourceTitle":"Video Bahasa Indonesia SMALB_B Karya Mulia Surabaya"}}],"example":"Hujan merupakan salah satu peristiwa alam.","video":{"id":"cvwI6-6lfGY","title":"Memahami teks eksplanasi","creator":"SMALB KM","topic":"Teks eksplanasi","sourceLevel":"SMALB-B","audience":"tunarungu","accessibility":"Isyarat & teks pada layar","description":"Pelajari teks eksplanasi dari SMALB-B Karya Mulia Surabaya melalui penjelasan isyarat dan teks yang tampil di layar.","sourceTitle":"Video Bahasa Indonesia SMALB_B Karya Mulia Surabaya"}}'::jsonb,'published') on conflict(id) do nothing;
